-- panel damage rules (carSurfaceFx/panelrules.lua)
local P = require('carSurfaceFx/panelrules')
local function near(a, b, e, m) assert(math.abs(a - b) <= (e or 1e-9), (m or '') .. ': ' .. tostring(a) .. ' vs ' .. tostring(b)) end
local d = P.defaults()
assert(d.enabled == false and d.metal == true and d.minEnergy == 60 and d.maxMarks == 40, 'off by default')
near(P.effectiveMass(1200, 800), 6, 1e-9, 'mass share times 4')
assert(P.effectiveMass(0, 0) == 20 and P.effectiveMass(5000, 10) == 60 and P.effectiveMass(10, 1000) == 5, 'mass clamped, unknown mass 20')
near(P.energy(2, 0, 1200, 800), 0.5 * 6 * 4, 1e-9, 'tap by speed')
near(P.energy(0.1, 30000, 1200, 800), 60, 1e-9, 'a force over a small give wins when it is more')
assert(P.energy(nil, nil, nil, nil) == 0 and P.energy(-3, 0, 1200, 800) == P.energy(3, 0, 1200, 800), 'missing numbers, sign')
assert(P.severity(10, 60) == 0 and P.severity(60, 60) == 0.1 and P.severity(1200, 60) == 1 and P.severity(1e9, 60) == 1, 'severity ends')
assert(P.severity(200, 60) > P.severity(100, 60), 'harder is deeper')
near(P.radius(0, 1), 0.04, 1e-9, 'tap radius') near(P.radius(1, 1), 0.14, 1e-9, 'crease radius') near(P.radius(1, 2), 0.28, 1e-9, 'amount') near(P.radius(1, 99), 0.42, 1e-9, 'amount clamped')
assert(P.kindOf({ nodeMaterial = P.NODE.METAL }) == 'metal' and P.kindOf({ nodeMaterial = P.NODE.PLASTIC }) == 'plastic' and P.kindOf(nil) == 'metal', 'metal is the fallback, plastic nodes are plastic')
assert(P.kindOf({ nodeMaterial = P.NODE.RUBBER }) == 'plastic' and P.kindOf({ nodeMaterial = P.NODE.GLASS }) == nil, 'rubber trim is plastic, glass is not a panel')
local on = { enabled = true, metal = true, plastic = false, fibreglass = true, carbon = true, minEnergy = 60 }
assert(P.accept(on, 'metal', 100, 5, 0) == true, 'accepted')
assert(P.accept({ enabled = false, metal = true, minEnergy = 60 }, 'metal', 100, 5, 0) == false, 'master off')
assert(P.accept({ enabled = true, metal = false, minEnergy = 60 }, 'metal', 100, 5, 0) == false, 'metal off')
assert(P.accept(on, 'metal', 10, 5, 0) == false, 'under the minimum')
assert(P.accept(on, 'metal', 100, 5, 6) == false and P.accept(on, 'metal', 100, 6, 6) == true, 'cooldown')
assert(P.accept(on, 'plastic', 100, 5, 0) == false, 'the plastic switch off')
assert(P.accept(on, 'carbon', 100, 5, 0) == true and P.accept(on, 'fibreglass', 100, 5, 0) == true, 'carbon and fibreglass')
assert(P.accept(on, 'rubber', 100, 5, 0) == false and P.accept(on, nil, 100, 5, 0) == false, 'an unknown kind is refused')
assert(d.plastic and d.fibreglass and d.carbon, 'the new kinds default on once the master is on')
assert(P.closingSpeed(7.8, 0.8) == 2 and P.closingSpeed(1.2, nil) == 1.2 and P.closingSpeed(-5, 0) == 2, 'a jittery node speed counts at most 2 m/s; a car that barely changed speed is a tap')
assert(P.closingSpeed(0.5, 10.4) == 10.4 and P.closingSpeed(7.8, 1.0) == 1.0, 'a real speed change of the car is the closing speed')
local tap, wall20, wall40 = P.energy(P.closingSpeed(7.9, 0.8), 600, 1016, 796), P.energy(P.closingSpeed(5.7, 5.4), 500, 1016, 796), P.energy(P.closingSpeed(7.7, 10.6), 650, 1016, 796)
assert(tap < 60 and wall20 > 60 and wall40 > 4 * 60 * 0.9 and P.severity(wall40, 60) > P.severity(wall20, 60), 'a tap is below the minimum, a 20 km/h wall stop marks a little, a 40 km/h one much more')
print('carSurfaceFx panel rules: ok')
